    {
      "card_ids": ["C01"],
      "claim": "AM281 readily permeates the human BBB and is used as a SPECT/PET radioligand to quantify brain CB1 receptors, providing direct human evidence of CNS access for a structurally related chlorophenyl heteroaromatic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "[11C]CNY-01 showed good brain uptake and binding specificity in mouse PET imaging, supporting CNS penetration of this chlorophenyl heteroaromatic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "M4 PAM 15q showed excellent CNS penetration in rats with a brain:plasma Kp of 3.4, supporting meaningful brain exposure for a related heteroaromatic CNS agent.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Alpidem easily crossed the rat BBB with a brain/plasma ratio of about 2.0-2.5 and slow CNS efflux, supporting net brain accumulation for a close chlorophenyl fused-heteroaromatic analogue.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
